Given an array arr[] of positive integers, the task is the find the length of the longest sub-array with the maximum possible GCD value.Examples:  Input: arr[] = {1, 2, 2} Output: 2 Here all possible sub-arrays and there GCD's are: 1) {1} -> 1 2) {2} -> 2 3) {2} -> 2 4) {1, 2} -> 1 5) {2, 2} -> 2 6) {1, 2, 3} -> 1 Here, the maximum GCD value is 2 and longest sub-array having GCD = 2 is {2, 2}. Thus, the answer is {2, 2}.Input: arr[] = {3, 3, 3, 3} Output: 4 Naive approach:This method's temporal complexity is O(n^3), where n is the length of the input array, making it inefficient for large inputs. This is because each sub-array's GCD was calculated using nested loops that generated all of the sub-arrays.Follow the steps:Generate all sub-arraysCalculate GCD for each sub-arrayCheck for maximum GCD value, and update the maximum gcd and maximum length accordingly.Return the maximum lengthBelow is the implementation of the above approach:  
            C++

    #include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

// Function to calculate the greatest common divisor (GCD) of two numbers
int gcd(int a, int b) {
    while (b) {
        a %= b;
        swap(a, b); // Swapping values to continue the process
    }
    return a; // Return the GCD
}

// Function to find the length of the longest sub-array with maximum GCD value (naive approach)
int longestSubarrayNaive(vector<int>& arr) {
    int n = arr.size(); // Length of the input array
    int maxLength = 0; // Initialize the maximum length of sub-array
      int maxGcd=0;
    // Nested loops to generate all possible sub-arrays
    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            int subarrayGcd = arr[i]; // Initialize GCD value with the first element of the sub-array

            // Loop to calculate GCD of the sub-array elements
            for (int k = i + 1; k <= j; ++k) {
                subarrayGcd = gcd(subarrayGcd, arr[k]); // Update GCD value iteratively
            }


            if (subarrayGcd > maxGcd) {
                maxLength = j - i + 1; // Update the maximum length if condition satisfies
                  maxGcd=subarrayGcd;
            }
          else if(subarrayGcd == maxGcd)
          {
            maxLength = max(maxLength, j - i + 1);
          }
        }
    }

    return maxLength; // Return the length of the longest sub-array with maximum GCD
}

int main() {
    vector<int> arr1 = {1, 2, 2};
    vector<int> arr2 = {3, 3, 3, 3};

    // Example usage
    cout << "Longest sub-array length for arr1: " << longestSubarrayNaive(arr1) << endl; // Output: 2
    cout << "Longest sub-array length for arr2: " << longestSubarrayNaive(arr2) << endl; // Output: 4

    return 0;
}


