    {
        // To store the maximum number
        // present in the array
        int x = 0;

        // Finding the maximum element
        for (int i = 0; i < n; i++)
            x = Math.max(x, arr[i]);

        int ans = 0, count = 0;

        for (int i = 0; i < n; i++) {
            if (arr[i] == x) {
                count++;
                ans = Math.max(ans, count);
            } else {
